#[derive(Clone, Debug, PartialEq, Eq)]
pub struct CanonicalArtifactDto {
    pub schema: &'static str,
    pub canonical_payload_json: &'static str,
}

pub const CANONICAL_ARTIFACT: CanonicalArtifactDto = CanonicalArtifactDto {
    schema: ARTIFACT_SCHEMA,
    canonical_payload_json: ARTIFACT_CANONICAL_PAYLOAD_JSON,
};

#[derive(Clone, Debug, PartialEq, Eq)]
enum NativeWorkTag {
    Work0,
    Work1,
    Work2,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct NativeWorkRequestDto {
    work: NativeWorkTag,
    request_bytes: Box<[u8]>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct NativeReplyDto {
    response_bytes: Box<[u8]>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum NativeErrorKind {
    UnsupportedWork,
    MalformedRequest,
    ExecutionFailure,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct NativeErrorDto {
    pub kind: NativeErrorKind,
    pub detail: String,
}

impl NativeWorkRequestDto {
    pub fn tower256_dot_product(request_bytes: Box<[u8]>) -> Self {
        Self { work: NativeWorkTag::Work0, request_bytes }
    }

    pub fn baby_bear_add1_zero_witness(request_bytes: Box<[u8]>) -> Self {
        Self { work: NativeWorkTag::Work1, request_bytes }
    }

    pub fn evm_stage0_add_aux(request_bytes: Box<[u8]>) -> Self {
        Self { work: NativeWorkTag::Work2, request_bytes }
    }

    pub fn from_ids(
        work_id_decimal: &str,
        carrier_profile_id_decimal: &str,
        request_codec_id_decimal: &str,
        response_codec_id_decimal: &str,
        request_bytes: Box<[u8]>,
    ) -> Result<Self, NativeErrorDto> {
        if work_id_decimal == WORK_0_ID_DECIMAL {
            if carrier_profile_id_decimal != WORK_0_CARRIER_PROFILE_ID_DECIMAL
                || request_codec_id_decimal != WORK_0_REQUEST_CODEC_ID_DECIMAL
                || response_codec_id_decimal != WORK_0_RESPONSE_CODEC_ID_DECIMAL
            {
                return Err(NativeErrorDto {
                    kind: NativeErrorKind::MalformedRequest,
                    detail: "work identifier supplied with noncanonical profile or codec pins".into(),
                });
            }
            return Ok(Self::tower256_dot_product(request_bytes));
        }
        if work_id_decimal == WORK_1_ID_DECIMAL {
            if carrier_profile_id_decimal != WORK_1_CARRIER_PROFILE_ID_DECIMAL
                || request_codec_id_decimal != WORK_1_REQUEST_CODEC_ID_DECIMAL
                || response_codec_id_decimal != WORK_1_RESPONSE_CODEC_ID_DECIMAL
            {
                return Err(NativeErrorDto {
                    kind: NativeErrorKind::MalformedRequest,
                    detail: "work identifier supplied with noncanonical profile or codec pins".into(),
                });
            }
            return Ok(Self::baby_bear_add1_zero_witness(request_bytes));
        }
        if work_id_decimal == WORK_2_ID_DECIMAL {
            if carrier_profile_id_decimal != WORK_2_CARRIER_PROFILE_ID_DECIMAL
                || request_codec_id_decimal != WORK_2_REQUEST_CODEC_ID_DECIMAL
                || response_codec_id_decimal != WORK_2_RESPONSE_CODEC_ID_DECIMAL
            {
                return Err(NativeErrorDto {
                    kind: NativeErrorKind::MalformedRequest,
                    detail: "work identifier supplied with noncanonical profile or codec pins".into(),
                });
            }
            return Ok(Self::evm_stage0_add_aux(request_bytes));
        }
        Err(NativeErrorDto {
            kind: NativeErrorKind::UnsupportedWork,
            detail: format!("unsupported Lean work id {work_id_decimal}"),
        })
    }

    pub fn work_id_decimal(&self) -> &'static str {
        match self.work {
            NativeWorkTag::Work0 => WORK_0_ID_DECIMAL,
            NativeWorkTag::Work1 => WORK_1_ID_DECIMAL,
            NativeWorkTag::Work2 => WORK_2_ID_DECIMAL,
        }
    }

    pub fn carrier_profile_id_decimal(&self) -> &'static str {
        match self.work {
            NativeWorkTag::Work0 => WORK_0_CARRIER_PROFILE_ID_DECIMAL,
            NativeWorkTag::Work1 => WORK_1_CARRIER_PROFILE_ID_DECIMAL,
            NativeWorkTag::Work2 => WORK_2_CARRIER_PROFILE_ID_DECIMAL,
        }
    }

    pub fn request_codec_id_decimal(&self) -> &'static str {
        match self.work {
            NativeWorkTag::Work0 => WORK_0_REQUEST_CODEC_ID_DECIMAL,
            NativeWorkTag::Work1 => WORK_1_REQUEST_CODEC_ID_DECIMAL,
            NativeWorkTag::Work2 => WORK_2_REQUEST_CODEC_ID_DECIMAL,
        }
    }

    pub fn response_codec_id_decimal(&self) -> &'static str {
        match self.work {
            NativeWorkTag::Work0 => WORK_0_RESPONSE_CODEC_ID_DECIMAL,
            NativeWorkTag::Work1 => WORK_1_RESPONSE_CODEC_ID_DECIMAL,
            NativeWorkTag::Work2 => WORK_2_RESPONSE_CODEC_ID_DECIMAL,
        }
    }

    pub fn request_bytes(&self) -> &[u8] { &self.request_bytes }
}

impl NativeReplyDto {
    pub fn response_bytes(&self) -> &[u8] { &self.response_bytes }
    pub fn into_response_bytes(self) -> Box<[u8]> { self.response_bytes }
}

pub fn dispatch_native(
    request: NativeWorkRequestDto,
) -> Result<NativeReplyDto, NativeErrorDto> {
    match request.work {
        NativeWorkTag::Work0 => {
            let response = crate::native_dispatch::tower256_dot_product_bytes(&request.request_bytes).map_err(|error| NativeErrorDto {
                kind: NativeErrorKind::ExecutionFailure,
                detail: error.to_string(),
            })?;
            if response.len() != WORK_0_RESPONSE_WIDTH {
                return Err(NativeErrorDto {
                    kind: NativeErrorKind::ExecutionFailure,
                    detail: format!("native response has {} bytes, expected {}", response.len(), WORK_0_RESPONSE_WIDTH),
                });
            }
            Ok(NativeReplyDto { response_bytes: response.into_boxed_slice() })
        }
        NativeWorkTag::Work1 => {
            let response = crate::native_dispatch::baby_bear_add1_zero_witness_bytes(&request.request_bytes).map_err(|error| NativeErrorDto {
                kind: NativeErrorKind::ExecutionFailure,
                detail: error.to_string(),
            })?;
            if response.len() != WORK_1_RESPONSE_WIDTH {
                return Err(NativeErrorDto {
                    kind: NativeErrorKind::ExecutionFailure,
                    detail: format!("native response has {} bytes, expected {}", response.len(), WORK_1_RESPONSE_WIDTH),
                });
            }
            Ok(NativeReplyDto { response_bytes: response.into_boxed_slice() })
        }
        NativeWorkTag::Work2 => {
            let response = crate::native_dispatch::evm_stage0_add_aux_bytes(&request.request_bytes).map_err(|error| NativeErrorDto {
                kind: NativeErrorKind::ExecutionFailure,
                detail: error.to_string(),
            })?;
            if response.len() != WORK_2_RESPONSE_WIDTH {
                return Err(NativeErrorDto {
                    kind: NativeErrorKind::ExecutionFailure,
                    detail: format!("native response has {} bytes, expected {}", response.len(), WORK_2_RESPONSE_WIDTH),
                });
            }
            Ok(NativeReplyDto { response_bytes: response.into_boxed_slice() })
        }
    }
}
